class Program
{
    static bool AreBracketsBalanced(string input)
    {
        int balance = 0;
        foreach (char c in input)
        {
            if (c == '[') balance++;
            else if (c == ']') balance--;

            if (balance < 0) return false;
        }
        return balance == 0;
    }

    static string GenerateRandomBrackets(int count)
    {
        var random = new Random();
        var brackets = new char[count * 2];
        for (int i = 0; i < count; i++)
        {
            brackets[i] = '[';
            brackets[count + i] = ']';
        }
        return string.Concat(brackets.OrderBy(_ => random.Next()));
    }

    static void Main()
    {
        for (int i = 0; i < 9; i++)
        {
            var brackets = GenerateRandomBrackets(i);
            Console.WriteLine($"\"{brackets}\" is {(AreBracketsBalanced(brackets) ? "" : "not ")}balanced.");
        }
    }
}

