public class Program
{
    public static IEnumerable<int[]> Combinations(int m, int n)
    {
        if (m == 0) return new[] { new int[0] };

        return Enumerable.Range(1, n).SelectMany(i =>
            Combinations(m - 1, i - 1).Select(c => c.Prepend(i).ToArray())
        );
    }

    static void Main()
    {
        foreach (int[] c in Combinations(3, 5))
        {
            Console.WriteLine(string.Join(",", c));
            Console.WriteLine();
        }
    }
}

