func factorial(n int64) *big.Int {
	if n < 0 {
		return nil
	}
	r := big.NewInt(1)
	var f big.Int
	for i := int64(2); i <= n; i++ {
		f.SetInt64(i)
		r.Mul(r, &f)
	}
	return r
}

