int main(void) {
    char text[] = "the quick brown fox";
    char *words[16];
    int count = 0;
    char *token = strtok(text, " ");
    while (token != NULL && count < 16) {
        words[count] = token;
        count++;
        token = strtok(NULL, " ");
    }
    for (int i = count - 1; i >= 0; i--) {
        printf("%s", words[i]);
        printf(i > 0 ? " " : "\n");
    }
    return 0;
}

