#include <stdio.h>

int main(void) {
    int values[] = {8, 8, 2, 6};
    int length = (int)(sizeof(values) / sizeof(values[0]));
    for (int i = 0; i < length; i++) {
        for (int j = 0; j < length - 1 - i; j++) {
            if (values[j] > values[j + 1]) {
                int tmp = values[j];
                values[j] = values[j + 1];
                values[j + 1] = tmp;
            }
        }
    }
    for (int i = 0; i < length; i++) {
        printf(i ? ",%d" : "%d", values[i]);
    }
    printf("\n");
    return 0;
}

