import "fmt"

func bubble(values []int) []int {
	items := make([]int, len(values))
	copy(items, values)
	for i := 0; i < len(items); i++ {
		for j := 0; j < len(items)-1-i; j++ {
			if items[j] > items[j+1] {
				items[j], items[j+1] = items[j+1], items[j]
			}
		}
	}
	return items
}

func main() {
	fmt.Println(bubble([]int{10, 2, 33, 4}))
}

