#include <stdio.h>

#define MAX_NODES 16

struct node {
    int value;
    int next;
};

static struct node pool[MAX_NODES];
static int used = 0;

static int push_front(int head, int value) {
    if (used >= MAX_NODES) {
        return head;
    }
    pool[used].value = value;
    pool[used].next = head;
    used += 1;
    return used - 1;
}

static int reverse(int head) {
    int previous = -1;
    int current = head;
    while (current != -1) {
        int next = pool[current].next;
        pool[current].next = previous;
        previous = current;
        current = next;
    }
    return previous;
}

static void render(int head) {
    int current = head;
    while (current != -1) {
        printf("%d", pool[current].value);
        current = pool[current].next;
        if (current != -1) {
            printf(" -> ");
        }
    }
    printf("\n");
}

int main(void) {
    int values[] = {1, 2, 3, 4, 5};
    int count = (int)(sizeof(values) / sizeof(values[0]));
    int head = -1;
    for (int i = count - 1; i >= 0; i--) {
        head = push_front(head, values[i]);
    }
    render(head);
    render(reverse(head));
    return 0;
}

