#define MAX_ENTRIES 16

struct entry {
    char kind[10];
    int amount;
    int balance;
};

struct account {
    int balance;
    struct entry log[MAX_ENTRIES];
    int count;
};

static void record(struct account *a, const char *kind, int amount) {
    if (a->count < MAX_ENTRIES) {
        strncpy(a->log[a->count].kind, kind, sizeof(a->log[a->count].kind) - 1);
        a->log[a->count].kind[sizeof(a->log[a->count].kind) - 1] = '\0';
        a->log[a->count].amount = amount;
        a->log[a->count].balance = a->balance;
        a->count += 1;
    }
}

static void deposit(struct account *a, int amount) {
    a->balance += amount;
    record(a, "deposit", amount);
}

static void withdraw(struct account *a, int amount) {
    if (amount > a->balance) {
        record(a, "refused", amount);
        return;
    }
    a->balance -= amount;
    record(a, "withdraw", amount);
}

int main(void) {
    struct account a;
    a.balance = 40;
    a.count = 0;
    record(&a, "open", a.balance);
    struct { const char *kind; int amount; } ops[] = {
    {"deposit", 0},
    {"withdraw", 40},
    {"deposit", 1},
    };
    int count = (int)(sizeof(ops) / sizeof(ops[0]));
    for (int i = 0; i < count; i++) {
        if (strcmp(ops[i].kind, "deposit") == 0) {
            deposit(&a, ops[i].amount);
        } else {
            withdraw(&a, ops[i].amount);
        }
    }
    for (int i = 0; i < a.count; i++) {
        printf("%-9s %4d -> %4d\n", a.log[i].kind, a.log[i].amount, a.log[i].balance);
    }
    return 0;
}

#include <algorithm>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

std::vector<std::string> tokens(const std::string& text) {
    std::istringstream stream(text);
    std::vector<std::string> out;
    std::string word;
    while (stream >> word) out.push_back(word);
    return out;
}

std::map<std::string, int> counts(const std::vector<std::string>& words) {
    std::map<std::string, int> table;
    for (const auto& word : words) table[word] += 1;
    return table;
}

std::vector<std::pair<std::string, int>> ranked(const std::map<std::string, int>& table) {
    std::vector<std::pair<std::string, int>> rows(table.begin(), table.end());
    std::sort(rows.begin(), rows.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    return rows;
}

int main() {
    const std::string text = "add add remove add edit edit remove";
    auto rows = ranked(counts(tokens(text)));
    for (size_t i = 0; i < rows.size() && i < 4; ++i)
        std::cout << rows[i].first << ": " << rows[i].second << "\n";
    return 0;
}

#include <cstdio>
#include <string>
#include <vector>

struct Item {
    std::string name;
    int qty;
    double price;
};

std::vector<Item> available(const std::vector<Item>& stock) {
    std::vector<Item> out;
    for (const auto& item : stock)
        if (item.qty > 0) out.push_back(item);
    return out;
}

double total_value(const std::vector<Item>& rows) {
    double sum = 0.0;
    for (const auto& row : rows) sum += row.qty * row.price;
    return sum;
}

void render(const std::vector<Item>& rows) {
    for (const auto& row : rows)
        printf("%-8s %3d x %6.2f = %8.2f\n", row.name.c_str(), row.qty,
               row.price, row.qty * row.price);
}

int main() {
    std::vector<Item> stock = {
        {"hammer", 3, 12.0},
        {"saw", 0, 18.5},
        {"drill", 2, 45.0},
    };
    auto rows = available(stock);
    render(rows);
    printf("total %.2f\n", total_value(rows));
    return 0;
}

