#include <array>
#include <cstdio>

using Matrix = std::array<std::array<int, 3>, 3>;

Matrix transpose(const Matrix& m) {
    Matrix out{};
    for (size_t r = 0; r < 3; ++r)
        for (size_t c = 0; c < 3; ++c) out[c][r] = m[r][c];
    return out;
}

std::array<int, 3> row_sums(const Matrix& m) {
    std::array<int, 3> sums{};
    for (size_t r = 0; r < 3; ++r)
        for (size_t c = 0; c < 3; ++c) sums[r] += m[r][c];
    return sums;
}

void render(const Matrix& m) {
    for (const auto& row : m) {
        for (int value : row) printf("%4d", value);
        printf("\n");
    }
}

int main() {
    Matrix m = {{
        {4, 4, 0},
        {0, 4, 4},
        {4, 0, 4},
    }};
    render(transpose(m));
    auto sums = row_sums(m);
    printf("sums %d %d %d\n", sums[0], sums[1], sums[2]);
    return 0;
}

#include <cstdio>
#include <string>
#include <utility>
#include <vector>

struct Entry {
    std::string kind;
    int amount;
    int balance;
};

struct Account {
    int balance;
    std::vector<Entry> log;

    Account(int opening) : balance(opening) {}

    void deposit(int amount) {
        balance += amount;
        log.push_back({"deposit", amount, balance});
    }

    bool withdraw(int amount) {
        if (amount > balance) {
            log.push_back({"refused", amount, balance});
            return false;
        }
        balance -= amount;
        log.push_back({"withdraw", amount, balance});
        return true;
    }
};

std::vector<Entry> run(int opening, const std::vector<std::pair<std::string, int>>& ops) {
    Account account(opening);
    account.log.push_back({"open", opening, opening});
    for (size_t i = 1; i < ops.size(); ++i) {
        if (ops[i].first == "deposit") account.deposit(ops[i].second);
        else account.withdraw(ops[i].second);
    }
    return account.log;
}

int main() {
    std::vector<std::pair<std::string, int>> ops = {
        {"open", 45},
        {"deposit", 5},
        {"withdraw", 50},
        {"withdraw", 0},
    };
    for (const auto& row : run(ops.front().second, ops))
        printf("%-9s %4d -> %4d\n", row.kind.c_str(), row.amount, row.balance);
    return 0;
}

using System;
using System.Collections.Generic;
using System.Linq;

class WordFreq
{
    static List<string> Tokens(string text) =>
        text.Split(' ', StringSplitOptions.RemoveEmptyEntries).ToList();

    static Dictionary<string, int> Counts(List<string> words)
    {
        var table = new Dictionary<string, int>();
        foreach (var word in words)
            table[word] = table.TryGetValue(word, out var n) ? n + 1 : 1;
        return table;
    }

    static List<KeyValuePair<string, int>> Ranked(Dictionary<string, int> table) =>
        table.OrderByDescending(pair => pair.Value)
             .ThenBy(pair => pair.Key, StringComparer.Ordinal)
             .ToList();

    static void Main()
    {
        var text = "alpha beta gamma alpha beta alpha";
        foreach (var row in Ranked(Counts(Tokens(text))).Take(4))
            Console.WriteLine($"{row.Key}: {row.Value}");
    }
}

