class Inventory
{
    static List<(string Name, int Qty, double Price)> Available(
        List<(string Name, int Qty, double Price)> stock) =>
        stock.Where(item => item.Qty > 0).ToList();

    static double TotalValue(List<(string Name, int Qty, double Price)> rows) =>
