struct Entry {
    kind: String,
    amount: i32,
    balance: i32,
}

struct Account {
    balance: i32,
    log: Vec<Entry>,
}

impl Account {
    fn open(amount: i32) -> Account {
        Account {
            balance: amount,
            log: vec![Entry { kind: "open".to_string(), amount, balance: amount }],
        }
    }

    fn deposit(&mut self, amount: i32) {
        self.balance += amount;
        self.log.push(Entry {
            kind: "deposit".to_string(),
            amount,
            balance: self.balance,
        });
    }

    fn withdraw(&mut self, amount: i32) {
        if amount > self.balance {
            self.log.push(Entry {
                kind: "refused".to_string(),
                amount,
                balance: self.balance,
            });
            return;
        }
        self.balance -= amount;
        self.log.push(Entry {
            kind: "withdraw".to_string(),
            amount,
            balance: self.balance,
        });
    }
}

fn main() {
    let ops: Vec<(&str, i32)> = vec![
        ("deposit", 500),
        ("withdraw", 250),
        ("withdraw", 255),
    ];
    let mut account = Account::open(5);
    for (kind, amount) in ops {
        if kind == "deposit" {
            account.deposit(amount);
        } else {
            account.withdraw(amount);
        }
    }
    for entry in &account.log {
        println!("{:<9} {:>4} -> {:>4}", entry.kind, entry.amount, entry.balance);
    }
}

