namespace DecimalBinaryConverter
{
    internal class Program
    {
        static void Main(string[] args)
        {
            if (args.Length == 0)
            {
                Console.WriteLine("Please provide a decimal number as an argument.");
                return;
            }

            try
            {
                int decimalNumber = Convert.ToInt32(args[0]);
                string binaryRepresentation = DecimalToBinary(decimalNumber);
                Console.WriteLine($"Decimal: {decimalNumber} ===> Binary: {binaryRepresentation}");
            }
            catch (FormatException)
            {
                Console.WriteLine("Invalid input. Please enter a valid integer.");
            }
        }

        static string DecimalToBinary(int decimalNumber)
        {
            if (decimalNumber == 0) return "0";

            string binary = "";
            while (decimalNumber > 0)
            {
                int remainder = decimalNumber % 2;
                binary = remainder + binary;
                decimalNumber /= 2;
            }

            return binary;
        }
    }
}

